import clsx from 'clsx';
import React, { forwardRef } from 'react';
import { isElement } from 'react-is';

import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';
import { Text } from '../../../typography/Text.js';
import { detailsSlotCss } from '../EmptyState.sty.js';

//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface EmptyStateDetailsProps
  extends WithChildren,
    StylingProps,
    DataTestId {}
//#endregion Typings

/**
 * Typeguard function that will check if a React.Node is a EmptyState.Details
 * @internal
 */
export function _isEmptyStateDetails(
  child: React.ReactNode,
): child is React.ReactElement<EmptyStateDetailsProps> {
  return isElement(child) && child.type === Details;
}

/** The Details slot of the EmptyState component. */
export const Details = /* @__PURE__ */ forwardRef<
  HTMLParagraphElement,
  EmptyStateDetailsProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  return (
    <Text
      ref={forwardedRef}
      className={clsx([detailsSlotCss, consumerClassName])}
      style={consumerStyle}
      data-testid={dataTestId}
      textStyle="base"
      as="p"
    >
      {children}
    </Text>
  );
});

(Details as typeof Details & { displayName: string }).displayName =
  'EmptyState.Details';
